diff --git a/src/liblzma/common/index.c b/src/liblzma/common/index.c
index 3415855..f265f53 100644
--- a/src/liblzma/common/index.c
+++ b/src/liblzma/common/index.c
@@ -772,8 +772,7 @@ lzma_index_append(lzma_index *i, const lzma_allocator *allocator,
 		++g->last;
 	} else {
 		// We need to allocate a new group. Keep a single group at
-		// INDEX_GROUP_SIZE Records at most; g->allocated is the number
-		// of slots reserved in records[].
+		// INDEX_GROUP_SIZE Records at most.
 		assert(i->prealloc > 0);
 		const size_t slots = i->prealloc > INDEX_GROUP_SIZE
 				? (size_t)INDEX_GROUP_SIZE : i->prealloc;
@@ -786,6 +785,12 @@ lzma_index_append(lzma_index *i, const lzma_allocator *allocator,
 		g->last = 0;
 		g->allocated = slots;

+		// group_hint stays at the Record count requested for this Index
+		// after prealloc is reset below. Manual appends leave the hint at
+		// INDEX_GROUP_SIZE, which is the same as slots.
+		if (i->group_hint > g->allocated)
+			g->allocated = i->group_hint;
+
 		// Reset prealloc so that if the application happens to
 		// add new Records, the allocation size will be sane.
 		i->prealloc = INDEX_GROUP_SIZE;

diff --git a/src/liblzma/common/index.c b/src/liblzma/common/index.c
index f3020b5..863ddf5 100644
--- a/src/liblzma/common/index.c
+++ b/src/liblzma/common/index.c
@@ -726,6 +726,17 @@ lzma_index_stream_padding(lzma_index *i, lzma_vli stream_padding)
 }


+/// Slot count for one Record group. Never more than INDEX_GROUP_SIZE.
+static size_t
+index_group_alloc_slots(size_t hint)
+{
+	if (hint > INDEX_GROUP_SIZE)
+		return (size_t)INDEX_GROUP_SIZE;
+
+	return hint;
+}
+
+
 extern LZMA_API(lzma_ret)
 lzma_index_append(lzma_index *i, const lzma_allocator *allocator,
 		lzma_vli unpadded_size, lzma_vli uncompressed_size)
@@ -777,8 +788,10 @@ lzma_index_append(lzma_index *i, const lzma_allocator *allocator,
 		// We need to allocate a new group. Keep a single group at
 		// INDEX_GROUP_SIZE Records at most.
 		assert(i->prealloc > 0);
-		const size_t slots = i->prealloc > INDEX_GROUP_SIZE
-				? (size_t)INDEX_GROUP_SIZE : i->prealloc;
+		size_t slots = i->prealloc;
+		if (slots > INDEX_GROUP_SIZE)
+			slots = (size_t)INDEX_GROUP_SIZE;
+		slots = index_group_alloc_slots(slots);
 		g = lzma_alloc(sizeof(index_group)
 				+ slots * sizeof(index_record),
 				allocator);
